sp_widget.css:
.profile-grid{
display:grid;
grid-template-columns:1fr 1fr;
gap:28px;
}

.profile-card{

background:white;

border-radius:22px;

padding:36px;

box-shadow:
0 12px 40px rgba(0,0,0,.06);

}

.profile-card h2{

font-size:26px;

font-weight:800;

margin-bottom:32px;

color:#12357D;

}

.info-item,
.org-item{

background:#F4F7FD;

padding:18px 22px;

border-radius:16px;

margin-bottom:18px;

display:flex;

flex-direction:column;

border-left:5px solid #4472D8;

}

.info-item label,
.org-item{

font-weight:700;

color:#555;

font-size:15px;

}

.info-item span,
.org-item span{

margin-top:10px;

font-size:26px;

font-weight:700;

color:#163A82;

}

.active{

color:#0FA958!important;

}

.inactive{

color:#E5484D!important;

}

@media(max-width:900px){

.profile-grid{

grid-template-columns:1fr;

}

}

sp_widget.script:
(function() {

var sysId = $sp.getParameter('sys_id');

if (!sysId)
return;

var gr =
new GlideRecord(
'x_1902481_employ_0_employee'
);

if (gr.get(sysId)) {

data.manager =
gr.manager? gr.manager.getDisplayValue(): 'Not Assigned';

data.department =
gr.department? gr.department.getDisplayValue(): '';

data.employee_id =
gr.employee_id.toString();

data.active =
gr.active == true;

}

})();
